export const combineInitialState = reducers => {
    
  const globalState = {};

  // set default state returned by reducer and its reducer
  for (const [key, value] of Object.entries(reducers)) {
    
    if (typeof value === "function") {
      globalState[key] = value(undefined, { type: "__@@PLACEHOLDER_ACTION__" });
    } else {
      console.error(`${value} is not a function`);
    }
    
  }

    var result;
    
      result = Object.keys(globalState).reduce(function (r, k) {
        return r.concat(globalState[k]);
    }, []);
      
  const flatten = result => result.reduce((res, {name, children = []}) => res.concat(name).concat(flatten(children)), []);
  
  console.log(flatten)
  /**
   * Global reducer function; this is passed to the useReducer hook
   *
   * @param {object} state
   * @param {object} action
   */

  
  // return the initial state and the global reducer
  return [globalState];
};
